SYS-03.walkthrough_ar:
تطبيق نمط تجديد التوكنات الآمن ضد سباق العمليات باستخدام OkHttp Authenticator و Mutex:
```kotlin
class TokenAuthenticator @Inject constructor(
    private val sessionManager: SessionManager,
    private val authApi: Provider<AuthApiService>
) : Authenticator {
    private val mutex = Mutex()

    override fun authenticate(route: Route?, response: Response): Request? {
        val currentToken = sessionManager.getAccessToken() ?: return null
        // التحقق مما إذا كان طلب آخر قد أتم التجديد بالفعل
        if (response.request.header("Authorization") != "Bearer $currentToken") {
            return response.request.newBuilder().header("Authorization", "Bearer $currentToken").build()
        }
        return runBlocking {
            mutex.withLock {
                val freshToken = sessionManager.getAccessToken()
                if (freshToken != currentToken) {
                    return@withLock response.request.newBuilder().header("Authorization", "Bearer $freshToken").build()
                }
                val newTokens = authApi.get().refreshToken(sessionManager.getRefreshToken() ?: "")
                if (newTokens.isSuccessful) {
                    sessionManager.updateTokens(newTokens.body()!!.access, newTokens.body()!!.refresh)
                    response.request.newBuilder().header("Authorization", "Bearer ${newTokens.body()!!.access}").build()
                } else {
                    sessionManager.clearSession()
                    null
                }
            }
        }
    }
}
```

