sealed interface PaymentState {
    data class Processing(val idempotencyKey: String) : PaymentState
    data class PendingVerification(val orderId: String) : PaymentState
    data class Succeeded(val transactionId: String) : PaymentState
    data class Failed(val error: String) : PaymentState
}

suspend fun executePayment(orderId: String): PaymentState = try {
    val res = api.pay(orderId, idempotencyKey)
    if (res.isSuccessful) PaymentState.Succeeded(res.body()!!.id) else PaymentState.Failed(res.message())
} catch (e: IOException) {
    // انقطاع الشبكة ليس فشلاً بل حالة معلقة حتى التحقق من السيرفر
    PaymentState.PendingVerification(orderId)
}
