suspend fun pollPaymentStatus(orderId: String, key: String): PaymentStatus {
    repeat(5) {
        val status = api.checkStatus(orderId, key)
        if (status.isFinal) return status
        delay(2000L)
    }
    return PaymentStatus.REQUIRES_MANUAL_SUPPORT
}
