SYS-06.walkthrough_ar:
تطبيق RemoteMediator لربط شبكة API بقاعدة بيانات Room مع إدارة مفاتيح الصفحات:
```kotlin
@OptIn(ExperimentalPagingApi::class)
class ArticleRemoteMediator(private val db: AppDatabase, private val api: ArticleApiService) : RemoteMediator<Int, ArticleEntity>() {
    override suspend fun load(loadType: LoadType, state: PagingState<Int, ArticleEntity>): MediatorResult {
        val page = when (loadType) {
            LoadType.REFRESH -> 1
            LoadType.PREPEND -> return MediatorResult.Success(endOfPaginationReached = true)
            LoadType.APPEND -> db.remoteKeysDao().getLastKey()?.nextKey ?: return MediatorResult.Success(true)
        }
        val res = api.getArticles(page, state.config.pageSize)
        db.withTransaction {
            if (loadType == LoadType.REFRESH) db.articleDao().clearAll()
            db.articleDao().insertAll(res.items)
            db.remoteKeysDao().insert(ArticleRemoteKeys(res.nextPage))
        }
        return MediatorResult.Success(endOfPaginationReached = res.items.isEmpty())
    }
}
```

