SYS-08.walkthrough_ar:
تطبيق محرك Feature Flags يدعم التقييم متعدد الطبقات وزر الإيقاف الفوري:
```kotlin
enum class FeatureFlag(val key: String, val defaultValue: Boolean) {
    NEW_CHECKOUT("new_checkout_enabled", false),
    DARK_MODE("dark_mode_enabled", true)
}

class FeatureFlagManager(private val prefs: SharedPreferences) {
    private val killSwitches = ConcurrentHashMap<String, Boolean>()

    fun isEnabled(flag: FeatureFlag): Boolean {
        if (killSwitches[flag.key] == true) return false
        return if (prefs.contains(flag.key)) prefs.getBoolean(flag.key, flag.defaultValue) else flag.defaultValue
    }

    fun isUserInBucket(userId: String, flagKey: String, percentage: Int): Boolean {
        val bucket = (userId + flagKey).hashCode().absoluteValue % 100
        return bucket < percentage
    }
}
```

